    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
            patch = [row[x0:x1 + 1] for row in grid[y0:y1 + 1]]
            objects.append(patch)

    # Compare equal-sized windows of the component panels. The same motif may
    # occupy only part of a larger component, so windows slide vertically;
    # horizontal crops are centered within their component bounding boxes.
    best = None
    for ai in range(len(objects)):
        for bi in range(ai + 1, len(objects)):
            A, B = objects[ai], objects[bi]
            ha, hb, wa, wb = len(A), len(B), len(A[0]), len(B[0])
            maxw = min(wa, wb)
            # Try widths from the common full width down to useful motif widths.
            for ww in range(maxw, min(5, maxw) - 1, -1):
                xa = (wa - ww) // 2
                xb = (wb - ww) // 2
                for hh in range(min(ha, hb), 1, -1):
                    for ya in range(ha - hh + 1):
                        for yb in range(hb - hh + 1):
                            matches = miss_a = miss_b = 0
                            for dy in range(hh):
